import (
	"fmt"
	"os"
	"os/signal"
	"syscall"

	"github.com/integrio-intropy/intropy-cli/internal/dashboard"
	"github.com/spf13/cobra"
)

type dashboardFlags struct {
	addr      string
	port      int
	noBrowser bool
}

var dashboardOpts dashboardFlags

var dashboardCmd = &cobra.Command{
	Use:   "dashboard [dir]",
	Short: "Launch the local integration dashboard",
	Long: "Start a local web dashboard that visualizes the integrations and systems scaffolded under dir " +
		"(default: the current directory) — their template, pinned source, version, scaffold values and " +
		"system topology. The dashboard is served from the CLI itself and opens in your browser; it does " +
		"not start any integration processes. Press Ctrl+C to stop.",
	Args: cobra.MaximumNArgs(1),
	RunE: func(cmd *cobra.Command, args []string) error {
		root := "."
		if len(args) == 1 {
			root = args[0]
		}
		if info, err := os.Stat(root); err != nil {
			return fmt.Errorf("dashboard: %w", err)
		} else if !info.IsDir() {
			return newUsageErrorf("dashboard: %s is not a directory", root)
		}

		ctx, cancel := signal.NotifyContext(cmd.Context(), os.Interrupt, syscall.SIGTERM)
		defer cancel()

		return dashboard.Serve(ctx, dashboard.Options{
			Root:        root,
			Addr:        dashboardOpts.addr,
			Port:        dashboardOpts.port,
			OpenBrowser: !dashboardOpts.noBrowser,
			Version:     version,
			Stdout:      cmd.OutOrStdout(),
			Stderr:      cmd.ErrOrStderr(),
		})
	},
}

func init() {
	f := dashboardCmd.Flags()
	f.StringVar(&dashboardOpts.addr, "addr", "127.0.0.1", "host/interface to bind")
	f.IntVarP(&dashboardOpts.port, "port", "p", 8730, "port to bind (0 picks a free port)")
	f.BoolVar(&dashboardOpts.noBrowser, "no-browser", false, "do not open the dashboard in a browser")
	rootCmd.AddCommand(dashboardCmd)
}

package dashboard

import (
	"fmt"
	"io/fs"
	"net/http"
	"path"
	"strings"

	"github.com/integrio-intropy/intropy-cli/web"
)

// staticHandler serves the embedded SPA. Real build assets (hashed JS/CSS) are
// served with their correct content types; unknown *routes* fall back to
// index.html so the SPA's client-side routing works on deep links and reloads.
//
// A missing *file* (a path with an extension, e.g. /assets/index-abc123.js) is
// a 404 rather than a fallback. Serving index.html there would answer a script
// request with HTML and a 200, which the browser rejects on its MIME check and
// reports only as an empty page — the failure mode when a binary is built
// without `make web`. A 404 names the missing file instead.
func staticHandler() (http.Handler, error) {
	sub, err := fs.Sub(web.Assets, "dist")
	if err != nil {
		return nil, fmt.Errorf("open embedded dashboard assets: %w", err)
	}
	index, err := fs.ReadFile(sub, "index.html")
	if err != nil {
		return nil, fmt.Errorf("embedded dashboard is missing index.html: %w", err)
	}
	fileServer := http.FileServerFS(sub)

	serveIndex := func(w http.ResponseWriter) {
		w.Header().Set("Content-Type", "text/html; charset=utf-8")
		_, _ = w.Write(index)
	}

	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		name := path.Clean(strings.TrimPrefix(r.URL.Path, "/"))
		if name == "." || name == "" || name == "index.html" {
			serveIndex(w)
			return
		}
		if _, err := fs.Stat(sub, name); err != nil {
			if path.Ext(name) != "" {
				http.NotFound(w, r)
				return
			}
			serveIndex(w)
			return
		}
		fileServer.ServeHTTP(w, r)
	}), nil
}

